    LOOP
        matched_student_id := NULL;
        SELECT id INTO matched_student_id
          FROM core.students
         WHERE tenant_id = mec_tenant_id AND ((NULLIF(roster_row->>'oldNumber', '') IS NOT NULL AND upper(student_number) = upper(roster_row->>'oldNumber')) OR student_number = roster_row->>'number')
         LIMIT 1;

        IF matched_student_id IS NOT NULL THEN
            UPDATE core.students
               SET student_number = roster_row->>'number',
                   full_name = roster_row->>'name',
                   profile = COALESCE(profile, '{}'::jsonb) || jsonb_build_object(
                       'roll', roster_row->>'number',
                       'dept', roster_row->>'abbreviation', 'departmentCode', roster_row->>'code',
                       'department', roster_row->>'department',
                       'gender', lower(roster_row->>'gender'),
                       'sportsHouse', roster_row->>'house',
                       'source', 'anna_university_roster_2026_09_03'
                   ),
                   updated_at = now()
             WHERE id = matched_student_id;

            UPDATE identity.users account
               SET display_name = roster_row->>'name',
                   profile = COALESCE(account.profile, '{}'::jsonb) || jsonb_build_object(
                       'roll', roster_row->>'number',
                       'dept', roster_row->>'abbreviation', 'departmentCode', roster_row->>'code',
                       'department', roster_row->>'department',
                       'gender', lower(roster_row->>'gender'),
                       'sportsHouse', roster_row->>'house'
                   ),
                   updated_at = now()
              FROM core.students student
             WHERE student.id = matched_student_id AND account.id = student.user_account_id;

            UPDATE identity.tenant_memberships membership
               SET profile = COALESCE(membership.profile, '{}'::jsonb) || jsonb_build_object(
                       'roll', roster_row->>'number',
                       'dept', roster_row->>'abbreviation', 'departmentCode', roster_row->>'code',
                       'department', roster_row->>'department',
                       'gender', lower(roster_row->>'gender'),
                       'sportsHouse', roster_row->>'house'
                   ),
                   updated_at = now()
              FROM core.students student
             WHERE student.id = matched_student_id
               AND membership.tenant_id = mec_tenant_id
               AND membership.user_id = student.user_account_id;
        END IF;
    END LOOP;

    preethi_profile := jsonb_build_object(
        'roll', '413225205021', 'dept', 'IT', 'departmentCode', '205',
        'department', 'B.Tech in Information Technology', 'gender', 'f',
        'sportsHouse', '3', 'residency', 'unassigned',
        'year', 'II', 'team', 'Students', 'section', 'A',
        'source', 'anna_university_roster_2026_09_03'
    );
    INSERT INTO identity.users (email, password_hash, display_name, initials, account_type, active, profile)
    VALUES ('student202@mec.local', crypt('Mec@2026', gen_salt('bf', 12)), 'Preethi S', 'PS', 'student', true, preethi_profile)
    ON CONFLICT (email) DO UPDATE SET display_name = EXCLUDED.display_name, initials = EXCLUDED.initials,
        account_type = 'student', active = true, profile = EXCLUDED.profile, updated_at = now()
    RETURNING id INTO preethi_user_id;

    INSERT INTO identity.tenant_memberships (tenant_id, user_id, roles, active, is_primary, profile)
    VALUES (mec_tenant_id, preethi_user_id, ARRAY['student']::text[], true, true, preethi_profile)
    ON CONFLICT (tenant_id, user_id) DO UPDATE SET roles = ARRAY['student']::text[], active = true,
        is_primary = true, profile = EXCLUDED.profile, updated_at = now();

    SELECT id INTO student_role_id FROM authz.roles
     WHERE tenant_id = mec_tenant_id AND lower(role_key) = 'student' LIMIT 1;
    IF student_role_id IS NOT NULL THEN
        INSERT INTO authz.user_roles (tenant_id, user_id, role_id, assigned_by)
        VALUES (mec_tenant_id, preethi_user_id, student_role_id, 'migration-0082')
        ON CONFLICT (tenant_id, user_id, role_id) DO NOTHING;
    END IF;

    INSERT INTO core.students (tenant_id, student_number, full_name, email, phone,
        applicant_id, application_id, admission_id, campus_id, department_id, program_id,
        batch_id, section_id, academic_year, admission_category, user_account_id, status, profile)
    SELECT mec_tenant_id, '413225205021', 'Preethi S', 'student202@mec.local', NULL,
        'anna-413225205021-applicant', 'anna-413225205021-application', 'anna-413225205021-admission',
        template.campus_id, template.department_id, template.program_id, template.batch_id,
        template.section_id, template.academic_year, 'unassigned', preethi_user_id, 'active', preethi_profile
      FROM core.students template
     WHERE template.tenant_id = mec_tenant_id AND template.profile->>'dept' IN ('IT', '205')
     ORDER BY template.created_at LIMIT 1
    ON CONFLICT (tenant_id, student_number) DO UPDATE SET full_name = EXCLUDED.full_name,
        email = EXCLUDED.email, user_account_id = EXCLUDED.user_account_id, status = 'active',
        profile = EXCLUDED.profile, updated_at = now();
END $$;
